(53183, 'Psalms 55:21', 'Psalms', 55, 21, 'د ده خبرې وې خوږې له شاتو خو په زړه کې د جګړې اراده د ده خبرې له ورېښمو پستې خو پرېکول یې کړل د تورو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms55_verse_21.mp3', '', 1761754199, 1761754199),
(53184, 'Psalms 55:22', 'Psalms', 55, 22, 'خپل مشکلات دې څښتن ته پرېږده هغه به وکاندي ساتنه د ستا هغه به هېڅکله پرېنږدي نېکان خلک چې دوی وغورځیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms55_verse_22.mp3', '', 1761754199, 1761754199),
